from research_helpers import *
base='https://battery-materials.basf.com/global/en/solutions/cathode-active-materials'
a=ev(base,'Current battery-material portfolio identifies HED family and named cathode compositions; marketing categories not invented as separate products.')
products=[p('BASF HED','High-energy-density cathode active material family for lithium-ion batteries; overlaps individual named compositions.',a,life='commercial',typ='product',sector='energy_storage',sub='batteries',roles=['commercial_partner'])];evidence=[a]
for name,slug,desc in [('NCA Ni80% PC','nca-ni80-PC','Polycrystalline nickel-cobalt-aluminium cathode material for high-power batteries.'),('NCM Ni91% PC','ncm-ni91-pc','High-nickel polycrystalline nickel-cobalt-manganese cathode material.'),('LCO HV SC blend','lco-hv-sc-blend','High-voltage lithium-cobalt-oxide single-crystal blended cathode material.'),('NCM Ni90% SC','ncm-ni90-SC','High-nickel single-crystal nickel-cobalt-manganese cathode material.'),('NCM Ni60% SC','ncm-ni60-sc','Single-crystal nickel-cobalt-manganese cathode material for battery longevity.')]:
 src=ev(base+'/'+slug,'Current named cathode-material page reviewed; composition identifier is material offering, not battery-cell SKU.');evidence.append(src);products.append(p('BASF '+name,desc,src,life='commercial',typ='product',sector='energy_storage',sub='batteries',roles=['commercial_partner']))
products.append(p('BASF NCA Ni89% PC blend','Named polycrystalline nickel-cobalt-aluminium blended cathode offering.',a,life='commercial',typ='product',sector='energy_storage',sub='batteries',roles=['commercial_partner']))
b=ev(base+'/lco-hv-sc-blend','Current page cross-links named NCM Ni83% PC offer; detail fetch timed out, so no additional specifications inferred.');evidence.append(b)
products.append(p('BASF NCM Ni83% PC','Named polycrystalline nickel-cobalt-manganese cathode offering.',b,life='commercial',typ='product',sector='energy_storage',sub='batteries',roles=['commercial_partner']))
co=dict(company_id='cmp_2fa8cc21-8e08-4f1b-aa3c-3cdc02359ffa',products=products,evidence=evidence,status='partial',coverage_note='Eight cathode-material family/composition offerings recorded. HED family overlaps named compositions; not eight independent cell models. Partial: broader battery binders/electrolytes/recycling technologies, semiconductor chemicals, enzymes/fermentation ingredients, historical battery-storage systems and legacy portfolio require review.')
assert len(products)==8
(out/'batch-0389.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
